CREATE TABLE IF NOT EXISTS `invitations` (`id` int AUTO_INCREMENT NOT NULL, `email` varchar(320) NOT NULL, `tokenHash` varchar(128) NOT NULL, `role` enum('user','admin') NOT NULL DEFAULT 'user', `expiresAt` timestamp NOT NULL, `acceptedAt` timestamp NULL, `revokedAt` timestamp NULL, `createdBy` int NOT NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `invitations_id` PRIMARY KEY(`id`), CONSTRAINT `invitations_tokenHash_unique` UNIQUE(`tokenHash`));
